public void updateStatus(PresenceType presenceType, String verboseStatus) {
  if (isLoggedIn()) {
    try {
      msnMessenger.getOwner().setStatus(((MSNTransport) getTransport()).convertJabStatusToMSN(presenceType));
    } catch (NullPointerException | RuntimeException e) {
      // Handle the exception, e.g., log the error or take appropriate action
      e.printStackTrace();
    }
  } else {
    try {
      msnMessenger.login();
    } catch (NullPointerException | RuntimeException e) {
      // Handle the exception, e.g., log the error or take appropriate action
      e.printStackTrace();
    }
  }
}
